-- Baseline snapshot: the full OSS schema at the Django leaf
-- (db/0183, runner/0043), generated from a database migrated by Django
-- itself (`manage.py migrate --no-input` at ed077eaf5;
-- Django 4.2.30, Postgres 16.15, scratch database ne380_django).
--
-- Regeneration: migrate an empty database with Django to the new leaf,
-- pg_dump --no-owner --inserts, then strip the `\restrict`/`\unrestrict`
-- psql wrappers, every `SET ...` / `set_config` line (the migrator runs
-- with its own timeouts; server defaults match the dump's), and the
-- `django_migrations` data rows (replaced by the stamp INSERT below, with
-- explicit ids in dump order and CURRENT_TIMESTAMP). 12 SET lines and 2
-- wrapper lines were stripped from this snapshot; see the NEWPIDASH-380
-- workpad. Two objects are recreated from Django's own emitted DDL
-- (see "Django-text fixups" below) so the stored expression trees match.
--
-- The stamp rows make a fallback Django see a fully migrated database
-- (`manage.py migrate --check` applies nothing). Data rows for the seeded
-- tables (auth_permission, django_content_type, prompt_template, loop_jobs)
-- are kept: they are what Django's own migrate leaves behind.
--
-- This snapshot never changes once cut: later schema changes arrive as
-- forward ports (FORWARDS) and native upgrades (NATIVE), never as a
-- re-cut. Applied once per database, inside one transaction.
--
--
-- PostgreSQL database dump
--


-- Dumped from database version 16.15 (Ubuntu 16.15-0ubuntu0.24.04.1)
-- Dumped by pg_dump version 16.15 (Ubuntu 16.15-0ubuntu0.24.04.1)




