INSERT INTO public.loop_jobs VALUES ('2026-11-22 00:19:39.463509-08', '2026-11-22 00:19:39.463518-08', NULL, '18ad7da3-d041-4824-bec7-9ec025d8a531', 'auto-close-merged', 'Auto-close merged-PR issues', 'Close issues when their PR merges', 'Checks your projects once a day and marks an issue Done when the pull request that implements it has been merged.', 'Review open issues in the projects you can access, oldest first. An issue is a candidate when it references a pull request — in its links, description, or comments. For each candidate, call get_pull_request_status on the PR URL. If — and only if — the tool reports state "merged", move the issue to a state in its project''s "completed" state group (use list_states to find one) and add a one-line comment naming the merged PR. If merge state is "unknown" or the issue''s state is already in the completed group, leave it untouched. Do not create or delete anything.', 15, false, true, '2026-11-22 00:19:39.462187-08', 'FREQ=DAILY;BYHOUR=3;BYMINUTE=0', 'UTC', NULL, NULL);


