-- Django-text fixups: recreate two objects from Django's own DDL.
-- Django-text fixups (NEWPIDASH-380): two objects whose pg_dump-deparsed DDL
-- does not round-trip to the same stored expression tree that Django's own
-- migrate leaves behind (a PG deparse quirk on nested ANY/IN coercions:
-- `IN ('a', ...)` analyzes per-element while the dump's
-- `ANY ((ARRAY[...]::text[]))` analyzes whole-array; same semantics,
-- different catalog text). The statements below are Django's own emitted DDL
-- (`manage.py sqlmigrate runner 0023` / `runner 0032`), so the stored trees
-- — and the catalog text — match a Django-migrated database byte for byte.
-- The dump-created versions are dropped first; nothing depends on them.
DROP INDEX IF EXISTS public.agent_run_one_active_per_work_item;
CREATE UNIQUE INDEX "agent_run_one_active_per_work_item" ON "agent_run" ("work_item_id") WHERE ("work_item_id" IS NOT NULL AND "status" IN ('queued', 'assigned', 'waiting_for_worktree', 'running', 'cancel_requested', 'awaiting_approval', 'awaiting_reauth'));
ALTER TABLE public.agent_run DROP CONSTRAINT IF EXISTS "agent_run_cloud_has_no_local_assignment";
ALTER TABLE "agent_run" ADD CONSTRAINT "agent_run_cloud_has_no_local_assignment" CHECK (("executor_kind" IN ('local_runner', 'managed_runner') OR ("executor_kind" = 'cloud_agent' AND "runner_id" IS NULL AND "pinned_runner_id" IS NULL AND "owner_id" IS NULL AND "assigned_at" IS NULL)));

